    cart_id AS cartId,
    quantity
FROM CART
WHERE user_id = #{userId}
  AND product_id = #{productId}
  AND cart_type = #{cartType}
  AND cart_id != #{cartId}
  AND (
        option_id = NULLIF(#{optionId}, '')
        OR (option_id IS NULL AND NULLIF(#{optionId}, '') IS NULL)
      )


    AND rental_start = NULLIF(#{rentalStart}, '')
    AND rental_end = NULLIF(#{rentalEnd}, '')


LIMIT 1

